import {YAMLException} from 'js-yaml'

import type {Diagnostic} from '@codemirror/lint'
import {linter} from '@codemirror/lint'
import {Compartment} from '@uiw/react-codemirror'
import {useMemo} from 'react'
import {parseDocument} from 'yaml'
import type {Node} from 'yaml'

import {useAppDispatch} from '../../../../../../../hooks/react-redux'
import {usePipelineId} from '../../../../hooks/pipeline'
import {parsePipeline} from '../../../EditPipelinePage.utils'
import {pipelineYaml} from '../../../slices/EditPipelinePage.slices'
import {useEditPipelineYAMLContext} from '../../EditPipelineYAMLContext/EditPipelineYAMLContext'

import useYamlSchema from './useYamlSchema'

export const lintCustomMarkClass = 'cm-lintRangeCustom-error'

export const linterYamlEditComponent = new Compartment()

function useYamlEditorErrors(onValidate: (value: boolean) => void, currentYaml: string) {
  const id = usePipelineId()
  const {cloudImagesQueryRef} = useEditPipelineYAMLContext()
  const {schema, validator} = useYamlSchema(currentYaml, cloudImagesQueryRef)
  const dispatch = useAppDispatch()
  const yamlLinterExtension = useMemo(
    () =>
      linter(
        view => {
          const {doc} = view.state
          let diagnostics: Diagnostic[] = []
          const severity = 'error'

          try {
            const docString = doc.toString()
            const parsedDoc = parseDocument(docString)
            const validate = validator.validate(parsedDoc.toJSON(), schema, {
              nestedErrors: true,
            })
            const isDocEmpty = !docString.trim()

            if (isDocEmpty) {
              diagnostics.push({
                from: 0,
                to: 0,
                markClass: lintCustomMarkClass,
                message: 'Yaml should not be empty',
                severity,
              })
            } else if (!validate.valid) {
              diagnostics = validate.errors.map(({path, stack}) => {
                const {range} = parsedDoc.getIn(path, true) as Node
                const [from = 0, to = 0] = range ?? []

                return {
                  from,
                  to,
                  message: stack,
                  markClass: lintCustomMarkClass,
                  severity,
                }
              })
            }

            // try to parse YAML
            parsePipeline(docString)
          } catch (error) {
            let message = (error as Error)?.message ?? 'An Unexpected Error Occurred'
            let line = doc.lineAt(0)

            // handle YAML parsing errors
            if (error instanceof YAMLException) {
              line = doc.lineAt(error.mark.position)
              message = error.message
            }

            diagnostics.push({
              from: line.from,
              to: line.to,
              markClass: lintCustomMarkClass,
              message,
              severity,
            })

            // eslint-disable-next-line no-console
            console.error('error', error)
          }

          onValidate(!diagnostics.length)
          dispatch(pipelineYaml.actions.setDiagnostics({id, diagnostics}))

          return diagnostics
        },
        {
          delay: 500,
        },
      ),
    [dispatch, id, onValidate, schema, validator],
  )

  return {
    yamlLinterExtension,
    yamlSchema: schema,
  }
}

export default useYamlEditorErrors
