import {LRLanguage, indentNodeProp, foldNodeProp, foldInside} from '@codemirror/language'

import type {SyntaxNode} from '@lezer/common'
import {parser} from '@lezer/yaml'

const yamlLanguage = LRLanguage.define({
  name: 'yaml',
  parser: parser.configure({
    props: [
      indentNodeProp.add({
        Stream: cx => {
          const node = cx.node.resolve(cx.pos, -1) as SyntaxNode | null

          for (let before = node; before && before.to >= cx.pos; before = before.parent) {
            if (before.name === 'BlockMapping' && (node?.name === ':' || node?.name === 'Pair')) {
              return cx.baseIndentFor(node) + cx.unit
            }

            if (node?.name === ':' || node?.name === 'Stream') {
              return cx.baseIndentFor(node) + cx.unit
            }

            if (before.name === 'BlockLiteralContent' && before.from < before.to) {
              return cx.baseIndentFor(before)
            }
            if (before.name === 'BlockLiteral') {
              return cx.baseIndentFor(before) + cx.unit
            }
            if (before.name === 'BlockSequence' || before.name === 'BlockMapping') {
              return cx.column(before.from, 1)
            }
            if (before.name === 'QuotedLiteral') {
              return null
            }
            if (before.name === 'Literal') {
              const col = cx.column(before.from, 1)
              if (col === cx.lineIndent(before.from, 1)) {
                return col
              }
              if (before.to > cx.pos) {
                return null
              }
            }
          }
          return null
        },
      }),
      foldNodeProp.add({
        'FlowMapping FlowSequence': foldInside,
        'BlockSequence BlockMapping BlockLiteral': (node, state) => ({
          from: state.doc.lineAt(node.from).to,
          to: node.to,
        }),
      }),
    ],
  }),
  languageData: {
    commentTokens: {line: '#'},
  },
})

export default yamlLanguage
