import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import {useMemo} from 'react'

import {useDarkOrLightTheme} from '../../../../../../../hooks/theme/useDarkOrLightTheme'
import {
  yamlEditorThemeEditorView,
  yamlEditorThemeHighlightStyle,
} from '../utils/extensions/yamlEditorThemeExtension'

function useYamlEditorTheme() {
  const selectedTheme = useDarkOrLightTheme()
  const isDark = selectedTheme === Theme.DARK

  return useMemo(() => [yamlEditorThemeEditorView(isDark), yamlEditorThemeHighlightStyle], [isDark])
}

export default useYamlEditorTheme
